{"implementation":"def solve(case):
    lines = case["payload"]["lines"]
    if not lines:
        return {"valid": False}
    state = None
    valid = True
    for line in lines:
        colon_index = line.find(":")
        if colon_index == -1:
            valid = False
            break
        prefix = line[:colon_index].strip()
        if state is None:
            if prefix != "Thought":
                valid = False
                break
        elif state == "Thought":
            if prefix not in ("Action", "Final"):
                valid = False
                break
        elif state == "Action":
            if prefix != "Observation":
                valid = False
                break
        elif state == "Observation":
            if prefix not in ("Thought", "Final"):
                valid = False
                break
        elif state == "Final":
            valid = False
            break
        state = prefix
    if state != "Final":
        valid = False
    return {"valid": valid}"}
